  "A post can have up to 4 images, 1 video or 1 PDF, one kind at a time. Remove the video first.": "يمكن أن يحتوي المنشور على 4 صور كحد أقصى أو فيديو واحد أو ملف PDF واحد، نوعًا واحدًا في كل مرة. أزل الفيديو أولًا.",
