  "A tick beside a name that tells members the profile or page really is who it says. You apply from your settings once your profile is complete, and the team reviews each request.": "علامة بجانب الاسم تُخبر الأعضاء أن الملف أو الصفحة لصاحبها فعلًا. تقدّم الطلب من إعداداتك بعد اكتمال ملفك، ويراجع الفريق كل طلب.",
