  "Africa has never lacked great minds. It has lacked the bridge between them. Charter Mission is the professional community where Africa and its diaspora build together: chapters, collaborators, opportunities, events and learning. Free and non-partisan.": "لم تفتقر أفريقيا يومًا إلى العقول العظيمة، بل افتقرت إلى الجسر الذي يصل بينها. Charter Mission هو المجتمع المهني الذي تبني فيه أفريقيا ومهجرها معًا: فروع ومتعاونون وفرص وفعاليات وتعلّم. مجاني وغير حزبي.",
