  "By selecting “Accept and continue” you agree to the current Terms of Use, Privacy Notice and Community Guidelines. We record the versions and the time you accepted them.": "باختيارك «قبول ومتابعة» فإنك توافق على شروط الاستخدام وإشعار الخصوصية وإرشادات المجتمع الحالية. نسجّل الإصدارات ووقت قبولك لها.",
