  "Charter Center is preparing your certificate. It appears here, and we email you, as soon as it’s ready. It’s also shared on the feed so the community can congratulate you.": "يُعدّ Charter Center شهادتك. ستظهر هنا وسنراسلك فور جاهزيتها. وستُشارك أيضًا في الموجز ليتمكن المجتمع من تهنئتك.",
