  "Is Charter Mission free?": "هل Charter Mission مجانية؟",
  "is live again.": "عادت للظهور.",
  "is live. Add a logo and publish your first post.": "منشورة الآن. أضف شعارًا وانشر أول منشور.",
  "is now verified. The tick shows beside the name everywhere.": "موثَّق الآن. تظهر العلامة بجانب الاسم في كل مكان.",
  "Is this you?": "هل هذا أنت؟",
  "is trending in Africa": "رائج في أفريقيا",
  "isn’t told who reported.": "بمن قدّم البلاغ.",
  "It arrives here to download, and is shared on the feed so the community can congratulate you.": "تصل هنا لتنزيلها، وتُشارك في الموجز ليتمكن المجتمع من تهنئتك.",
  "It disappears from the strip and from any highlight it is in.": "تختفي من الشريط ومن أي مجموعة مميَّزة تضمها.",
  "It goes live on Events straight away.": "تظهر في «الفعاليات» فورًا.",
  "It goes to the Charter Mission moderators, marked urgent because it comes from a chapter team. Only they can suspend an account.": "يُحال البلاغ إلى مشرفي Charter Mission بصفة عاجلة لأنه صادر عن فريق فرع. هم وحدهم من يستطيع إيقاف حساب.",
  "It goes to the Charter Mission moderators, marked urgent because it comes from a chapter team. To hide it from the chapter meanwhile, also send it back for review.": "يُحال البلاغ إلى مشرفي Charter Mission بصفة عاجلة لأنه صادر عن فريق فرع. لإخفاء المنشور عن الفرع في الأثناء، أعده أيضًا إلى المراجعة.",
  "It is hidden from the chapter and joins the Review tab, where anyone on the team can approve or decline it. {name} is told.": "يُخفى عن الفرع وينتقل إلى تبويب «للمراجعة»، حيث يستطيع أي عضو في الفريق الموافقة عليه أو رفضه. ويُبلَّغ {name} بذلك.",
  "It leaves the review queue. You can send a new request whenever you like.": "يخرج من قائمة المراجعة. يمكنك إرسال طلب جديد متى شئت.",
  "It may have been deleted by its author, removed by moderators, or shared only with members you’re not connected to.": "ربما حذفه كاتبه، أو أزاله المشرفون، أو شورك فقط مع أعضاء لست على صلة بهم.",
  "It may have been removed from Charter Center or taken off the Learning page. Other courses on the same topic are a search away.": "ربما أُزيلت من Charter Center أو من صفحة التعلّم. يمكنك البحث عن دورات أخرى في الموضوع نفسه.",
  "It may have been retired on Charter Center, or none of its courses are listed right now.": "ربما أُوقف على Charter Center، أو أن دوراته غير مدرجة حاليًا.",
  "It may have been reversed, or the link belongs to another account.": "ربما أُلغي القرار، أو أن الرابط يخص حسابًا آخر.",
  "It may have expired, been deleted, or be visible only to the author’s connections.": "ربما انتهت مدتها، أو حُذفت، أو أنها ظاهرة لزملاء صاحبها فقط.",
  "It may not be open yet, or it has closed. Check the link, or look at the exams that are open now.": "ربما لم يُفتح بعد، أو أُغلق. تحقق من الرابط، أو تصفح الاختبارات المفتوحة الآن.",
  "It may not exist, it may still be a draft, or it may have been unpublished by the Charter Mission team.": "ربما لا تكون موجودة، أو ما زالت مسودة، أو ألغى فريق Charter Mission نشرها.",
  "It shows next to your name across Charter Mission. Your community manager will share the chapter tools and next steps with you.": "تظهر بجانب اسمك في أنحاء Charter Mission. سيشاركك مدير المجتمع أدوات الفرع والخطوات التالية.",
  "It takes two minutes. You can finish your profile later.": "يستغرق الأمر دقيقتين. يمكنك إكمال ملفك لاحقًا.",
  "It will be removed from Articles, feeds, topics and bookmarks. Comments on it are removed too. This can’t be undone.": "سيُزال من المقالات والخلاصات والمواضيع والمحفوظات. وتُحذف التعليقات عليه أيضًا. لا يمكن التراجع عن ذلك.",
  "It will be removed from feeds, topics and bookmarks. Comments on it are removed too. This can’t be undone.": "سيُزال من الخلاصات والمواضيع والمحفوظات. وتُحذف تعليقاته أيضًا. لا يمكن التراجع عن ذلك.",
  "It won’t appear in {chapter}. {name} is told, and can still see the post themselves.": "لن يظهر في {chapter}. يُبلَّغ {name} بذلك ويبقى قادرًا على رؤية منشوره.",
  "It’s a quiet moment in the community — a good time to share what you’re working on.": "المجتمع هادئ الآن — وقت مناسب لمشاركة ما تعمل عليه.",
  "Italic": "مائل",
  "Its posts and followers are removed with it. This can’t be undone.": "تُحذف معها منشوراتها ومتابعوها. لا يمكن التراجع عن ذلك.",
  "Job": "وظيفة",
  "Jobs, fellowships and grants from members appear here.": "تظهر هنا وظائف الأعضاء وزمالاتهم ومنحهم.",
  "Jobs, fellowships, grants and calls for partners from the community. Apply with your profile in a couple of clicks.": "وظائف وزمالات ومنح ودعوات شراكة من المجتمع. تقدَّم بملفك الشخصي بنقرات قليلة.",
  "Jobs, fellowships, grants and calls for partners posted by Charter Mission members.": "وظائف وزمالات ومنح ودعوات شراكة ينشرها أعضاء Charter Mission.",
  "Jobs, fellowships, grants and calls for partners, posted by members and organisations. Apply without leaving the platform.": "وظائف وزمالات ومنح ودعوات للشراكة ينشرها الأعضاء والمنظمات. تقدّم دون مغادرة المنصة.",
  "Join": "انضم",
