  "JPEG, PNG or WebP, up to 5 MB. 1200 × 630 works best. Without one, the event gets the Charter Mission pattern.": "JPEG أو PNG أو WebP، حتى 5 ميغابايت. المقاس 1200 × 630 هو الأنسب. من دون صورة تحصل الفعالية على نقشة Charter Mission.",
  "JPEG, PNG or WebP. You can crop and zoom it before saving.": "JPEG أو PNG أو WebP. يمكنك قصّها وتكبيرها قبل الحفظ.",
