  "Keep your account safe: your password, where you’re signed in and two-step verification.": "حافظ على أمان حسابك: كلمة المرور، والأجهزة المسجَّل دخولها، والتحقق بخطوتين.",
  "Keep your password private. Passwords must be at least 12 characters and not commonly used.": "حافظ على سرية كلمة مرورك. يجب ألا تقل عن 12 حرفًا وألا تكون شائعة الاستخدام.",
