  "You sent a request": "أرسلت طلبًا",
  "You unblocked {name}. They can see your profile and contact you again.": "ألغيت حظر {name}. يمكنه رؤية ملفك والتواصل معك مجددًا.",
  "You unfollowed {name}": "ألغيت متابعة {name}",
