  "You were removed from": "تمت إزالتك من",
  "You won’t be able to edit the page or post as it. The owner can add you again.": "لن تتمكن من تعديل الصفحة أو النشر باسمها. يستطيع المالك إضافتك مجددًا.",
  "You won’t get its messages any more. An admin can add you back.": "لن تصلك رسائلها بعد الآن. يمكن لأحد المشرفين إعادتك.",
  "You won’t see each other’s posts or profiles, and any connection or follow between you is removed. They aren’t told.": "لن يرى أيٌّ منكما منشورات الآخر أو ملفه الشخصي، وتُزال أي علاقة زمالة أو متابعة بينكما. ولن يتم إبلاغه.",
  "You won’t see each other’s posts or profiles. Any connection or follow between you is removed, and they can’t message, mention or request to connect with you. They aren’t told.": "لن يرى أيٌّ منكما منشورات الآخر أو ملفه الشخصي. تُزال أي علاقة زمالة أو متابعة بينكما، ولن يتمكن من مراسلتك أو الإشارة إليك أو طلب التواصل معك. ولن يتم إبلاغه.",
  "You’ll be asked for a code when you sign in to the admin console.": "سيُطلب منك رمز عند دخول لوحة الإدارة.",
  "You’ll be signed out on every device. Download your data first if you want a copy.": "سيُسجَّل خروجك من كل الأجهزة. نزّل بياناتك أولًا إن أردت نسخة منها.",
  "You’ll get this chapter’s announcements": "ستصلك إعلانات هذا الفرع",
  "You’ll lose your place in the queue. You can join again later if there’s still a waitlist.": "ستفقد مكانك في الطابور. يمكنك الانضمام لاحقًا إذا بقيت قائمة الانتظار مفتوحة.",
